import { readFile, writeFile } from 'node:fs/promises';

const [regular, extraBold] = await Promise.all([
  readFile(new URL('../assets/fonts/BeVietnamPro-Regular.ttf', import.meta.url), 'base64'),
  readFile(new URL('../assets/fonts/BeVietnamPro-ExtraBold.ttf', import.meta.url), 'base64'),
]);

await writeFile(
  new URL('../src/app/[locale]/og-fonts.generated.ts', import.meta.url),
  [
    '// Generated by scripts/gen-og-fonts.mjs — do not edit. Fonts are embedded because Workers have no filesystem.',
    `export const beVietnamProRegular = '${regular}';`,
    `export const beVietnamProExtraBold = '${extraBold}';`,
    '',
  ].join('\n'),
);
